"use strict";function query(n){var r;const t=window.location.search;t&&n&&initDataFirstQuery(t);var u=$("#EmployeeId").val(),f=$("#Year").val(),e=$("#IncludeRequestTrans").prop("checked"),i=_global.root+"annualleave/employee?employeeId="+u+"&Year="+f+"&IncludeRequestTrans="+e;n||(r=i,window.history.replaceState(null,null,r));$.ajax({url:i,type:"POST",dataType:"html",beforeSend:function(){n||$(".loading-process").fadeIn(300)},success:function(n){$("#div-content").html(n);floatThead("table#data")},error:function(n,t,i){alert(t+": "+i)},complete:function(){n||$(".loading-process").fadeOut(300)}})}function initDataFirstQuery(n){var t=new URLSearchParams(n),u=t.get("employeeId"),i=t.get("Year"),r=t.get("IncludeRequestTrans"),f=r===null?!0:r.toLowerCase()=="true";$("#Year").val(i);$(".select--year .select-dropdown").val(i);$("#EmployeeId").val(u);$("#IncludeRequestTrans").prop("checked",f)}function deleteLeaveTrans(n){confirm("Are you sure you want to delete this leave transaction?",function(){$.post(_global.root+"annualleave/Delete",{leaveTransactionId:n},function(n){n.IsSuccessful?query(!1):alert(n.Message)})})}$(document).ready(function(){$("#submit").on("click",function(){query(!1)});query(!0)});